# Parse grids by replacing \\n with actual newlines and splitting
def parse_grid(text):
    text = text.replace('\\n', '\n').strip()
    # Skip header
    lines = []
    for line in text.split('\n')[1:11]:
        stripped = line.strip()
        if stripped and all(c.isdigit() or c == ' ' for c in stripped):
            parts = stripped.split()
            if len(parts) > 0:
                try:
                    row = [int(x) for x in parts[:29]]
                    lines.append(row)
                except:
                    pass
    return lines

