def get_all_horizontal_bars(grid, bar_value=None):
    bars = []
    h, w = len(grid), len(grid[0])
    for r in range(h):
        if bar_value is not None:
            run_start = None
            for c in range(w):
                if run_start is not None and grid[r][c] != bar_value:
                    if c - run_start >= 3:
                        bars.append((r, run_start, c-1, bar_value))
                    run_start = None
                elif run_start is None and grid[r][c] == bar_value:
                    run_start = c
            if run_start is not None and w - run_start >= 3:
                bars.append((r, run_start, w-1, bar_value))
        else:
            # Find any bar
            run_start = None
            prev_val = None
            for c in range(w):
                if run_start is None and prev_val is not None and grid[r][c] != prev_val:
                    if c - run_start >= 3:
                        bars.append((r, run_start, c-1, prev_val))
                    run_start = None
                    prev_val = None
                elif run_start is None and prev_val is None:
                    run_start = c
                    prev_val = grid[r][c]
                elif grid[r][c] == prev_val:
                    pass
                else:
                    run_start = c
                    prev_val = grid[r][c]
            if run_start is not None and prev_val is not None and w - run_start >= 3:
                bars.append((r, run_start, w-1, prev_val))
    return bars

